    const query: Record<string, string | number | boolean | Array<string | number | boolean> | undefined> = {};
    if (params?.sourceScope !== undefined) {
      query["source_scope"] = params?.sourceScope;
    }
    if (params?.sourceType !== undefined) {
      query["source_type"] = params?.sourceType;
    }
    if (params?.sourceId !== undefined) {
      query["source_id"] = params?.sourceId;
    }
    if (params?.topPriority !== undefined) {
      query["top_priority"] = params?.topPriority;
    }
    if (params?.includeClosed !== undefined) {
      query["include_closed"] = params?.includeClosed;
    }
    if (params?.limit !== undefined) {
      query["limit"] = params?.limit;
    }
    if (params?.afterCursor !== undefined) {
      query["after_cursor"] = params?.afterCursor;
    }

    return this.http.request(`/api/v1/orgs/${org}/task_epics`, { query });
